"""Exact pricing of an order."""

from dataclasses import dataclass
from decimal import ROUND_HALF_UP, Decimal
from typing import List

from .catalog import TAX_RATES

CENT = Decimal("0.01")
ZERO = Decimal("0.00")
_ORDER_DISCOUNT_FROM = Decimal("500.00")
_ORDER_DISCOUNT_RATE = Decimal("0.03")


@dataclass(frozen=True)
class QuoteLine:
    sku: str
    quantity: int
    unit: Decimal
    gross: Decimal
    discount: Decimal
    net: Decimal


@dataclass(frozen=True)
class Quote:
    lines: List[QuoteLine]
    subtotal: Decimal
    order_discount: Decimal
    tax: Decimal
    total: Decimal


def _round(value):
    return value.quantize(CENT, rounding=ROUND_HALF_UP)


def _negative(amount):
    """-amount, but zero stays a plain 0.00 (never -0.00)."""
    return ZERO if amount == 0 else -amount


def _share_out(nets, discount):
    """Share ``discount`` (positive) over ``nets`` by largest remainder, to the penny."""
    cents = [int(net * 100) for net in nets]
    total = sum(cents)
    pennies = int(discount * 100)
    floors = [c * pennies // total for c in cents]
    remainders = [c * pennies % total for c in cents]
    left = pennies - sum(floors)
    by_remainder = sorted(range(len(cents)), key=lambda i: (-remainders[i], i))
    for i in by_remainder[:left]:
        floors[i] += 1
    return [Decimal(f) / 100 for f in floors]


def price_order(order, catalog):
    """Price a whole order (see the README for the six steps)."""
    lines = []
    for sku, quantity in order.lines:
        unit = catalog[sku].price
        gross = _round(unit * quantity)
        if quantity >= 50:
            rate = Decimal("0.10")
        elif quantity >= 10:
            rate = Decimal("0.05")
        else:
            rate = Decimal(0)
        discount = _round(gross * rate)
        lines.append(QuoteLine(sku, quantity, unit, gross, _negative(discount), gross - discount))
    subtotal = sum((line.net for line in lines), ZERO)
    discount = ZERO
    if subtotal >= _ORDER_DISCOUNT_FROM:
        discount = _round(subtotal * _ORDER_DISCOUNT_RATE)
    shares = _share_out([line.net for line in lines], discount) if discount else [ZERO] * len(lines)
    tax = ZERO
    for line, share in zip(lines, shares):
        taxable = line.net - share
        tax += _round(taxable * TAX_RATES[catalog[line.sku].tax])
    tax = _round(tax)
    total = subtotal - discount + tax
    return Quote(lines, _round(subtotal), _negative(discount), tax, _round(total))
EOF
