"""What has shipped on an order, and what the shelves can ship now."""

import dataclasses


def shipped_so_far(order, movements):
    """Dict of SKU -> units already shipped on ``order`` (capped at the quantity ordered)."""
    note = "order " + order.id
    sent = {}
    for move in movements:
        if move.quantity < 0 and move.note == note:
            sent[move.sku] = sent.get(move.sku, 0) - move.quantity
    return {sku: min(quantity, sent.get(sku, 0)) for sku, quantity in order.lines}


def status(order, shipped):
    """``complete``, ``open`` or ``partial``."""
    if all(shipped[sku] >= quantity for sku, quantity in order.lines):
        return "complete"
    if all(shipped[sku] == 0 for sku, _ in order.lines):
        return "open"
    return "partial"


def shipped_order(order, shipped):
    """A copy of ``order`` holding only the shipped quantities (nothing shipped: no lines)."""
    lines = [(sku, shipped[sku]) for sku, _ in order.lines if shipped[sku] > 0]
    return dataclasses.replace(order, lines=lines)


def available_on(movements, sku, date):
    """Most of ``sku`` that can leave on ``date`` without any later stock going below zero."""
    ordered = sorted(
        (m for m in movements if m.sku == sku), key=lambda m: m.date
    )
    balance = 0
    lowest = None
    for move in ordered:
        balance += move.quantity
        if move.date <= date:
            lowest = balance  # stock after all movements on or before date
        elif balance < lowest:
            lowest = balance
        if lowest is None:
            lowest = balance if move.date > date else None
    return max(0, lowest if lowest is not None else 0)
